function persist(){if(remote){if(isDirty())pendingEdits[remote.id]={avatar:clone(draft.avatar),transform:clone(draft.transform),response:draft.response||'',baseContentRevision:remote.contentRevision};else delete pendingEdits[remote.id];}try{localStorage.setItem(KEY,JSON.stringify({version:1,profile,draft:remote||invite?localDraft:draft,activeWork:remote?.id||null,pendingEdits,inviteLinks,works}));storageFailed=false;return true;}catch{storageFailed=true;toast('浏览器存储已满。当前画面还在，请先导出作品或释放空间。',true);return false;}}
function toast(text,error=false){const t=$('#toast');t.textContent=text;t.className=error?'visible error':'visible';clearTimeout(t.timer);t.timer=setTimeout(()=>t.className='',4500);}
function commit(change){history.push(clone(draft));if(history.length>40)history.shift();redo=[];change(draft);persist();render();}
function isDirty(){if(!remote)return false;const me=remote[remote.role];return JSON.stringify(safeAvatar(draft.avatar))!==JSON.stringify(safeAvatar(me.avatar))||JSON.stringify(draft.transform)!==JSON.stringify(me.transform)||(remote.role==='guest'&&(draft.response||'')!==(me.response||''));}
function requireClean(){if(!isDirty())return true;openModal(`<h2>先收好你的调整。</h2><p class="modal-intro">画面里还有未保存的改动。保存后，双方会确认这个新版本。</p><div class="modal-actions">${button('discard-shared','放弃这次调整','secondary')}${button('save-shared-modal','保存我的调整','primary')}</div>`);return false;}
function currentHost(){return invite?invite.host:remote?remote.host:{name:profile?.name||'你',avatar:draft.avatar,transform:draft.transform};}
function currentGuest(){if(invite)return {name:profile?.name||'我',avatar:draft.avatar,transform:draft.transform};if(remote?.guest)return remote.guest;if(draft.scene.id==='fan-stage')return {name:'月白 · 虚构音乐人',avatar:{skin:0,hair:3,hairColor:3,outfit:2,accessory:'none',pose:'sing'},transform:{x:68,y:80,scale:.92,rotation:3},fiction:true};return null;}
function isGuest(){return Boolean(invite||remote?.role==='guest');}
function myAvatar(){return draft.avatar;}
function statusLabel(){if(isDirty())return '有调整尚未保存';if(invite)return '入镜邀请';if(!remote)return '本机私密草稿';if(remote.exportEligible)return '已共同确认';if(remote.status==='pending')return isGuest()?'等待对方确认':'朋友已入镜';if(remote.status==='accepted')return '等待保存许可';if(remote.status==='rejected')return '可重新调整';return '等待朋友入镜';}
