 if(toonLayer?.parentNode)toonLayer.remove();
 const ss=draft.scene.kind==='photo'?{name:'我的现场',tag:'YOUR PHOTO'}:(scenes.find(s=>s.id===draft.scene.id)||scenes[0]);
 app.innerHTML=`<header class="topbar"><a class="brand" href="#" aria-label="Space 创作间"><span class="brand-mark"><i></i><i></i></span>space<span class="brand-sub">YOUR NEXT COVER</span></a><nav aria-label="主导航">${button('studio',`${ic('star')}创作间`,view==='studio'?'nav active':'nav')}${button('works',`${ic('grid')}我的作品 <span class="nav-count">${works.length}</span>`,view==='works'?'nav active':'nav')}</nav>${button('avatar',`<span class="profile-mini">${avatarSVG(profile?.avatar||DEFAULT_AVATAR)}</span><span>${e(profile?.name||'创建我的分身')}</span>`, 'profile-btn','aria-label="编辑我的分身"')}</header>
 ${routeLoading?`<div class="route-banner" role="status">正在读取这张共同作品… ${button('cancel-route','先回私密草稿','text-btn')}</div>`:''}${network?'<div class="network-banner" role="status">暂时离线 · 本机创作照常保存，邀请与共同作品将在联网后继续</div>':''}
 <main id="main" tabindex="-1" aria-busy="${routeLoading}" class="${routeLoading?'route-loading':''}">${view==='works'?worksPage():`<section class="studio-heading"><div><div class="eyebrow">SPACE / MUSIC × IDENTITY</div><h1>${invite?`${e(invite.host.name)} 给你留了个位置`:'今晚的封面，缺你。'}<span class="hand-star">✧</span></h1><p>${invite?'带上自己的分身，给这张作品一个你的回应。':'带着自己的样子，和朋友一起出演。'}</p></div><div class="connection"><i class="${connected?'online':''}"></i>${connected?'双人共创已连接':connected===null?'正在连接共创服务':'本机创作模式'}${button('about',ic('info'),'tiny','aria-label="了解保存与隐私"')}</div></section>
 <section class="workspace" aria-label="双人创作工作室"><aside class="identity-rail"><div class="rail-label">今晚的我 <span>01</span></div><button data-action="avatar" class="identity-card"><div class="avatar-pedestal">${avatarSVG(myAvatar())}<span class="spark s1">✧</span><span class="spark s2">+</span></div><strong>${e(profile?.name||'还没有名字的你')}</strong><span class="identity-edit">${profile?'换个造型':'创造你的分身'} ${ic('arrow')}</span></button><p class="rail-note">一个分身，<br>很多种登场方式。</p><div class="rail-divider"></div><div class="rail-label">你的出演方式</div><div class="pose-list">${POSES.map(([id,label])=>button('pose',`<span class="pose-dot">${{sway:'♫',wave:'✦',sing:'♪',listen:'☾'}[id]}</span>${label}`,draft.avatar.pose===id?'pose active':'pose',`data-value="${id}" aria-pressed="${draft.avatar.pose===id}"`)).join('')}</div><div class="rail-foot">${ic('lock')}默认私密 · 由你决定分享</div></aside>
 <div class="canvas-column"><div class="canvas-toolbar"><span class="canvas-tab">${ic('photo')} ${e(invite?.title||draft.title)}</span><div>${button('undo',ic('undo'),'icon-btn',`aria-label="撤销" ${history.length?'':'disabled'}`)}${button('redo',ic('redo'),'icon-btn',`aria-label="重做" ${redo.length?'':'disabled'}`)}${button('preview',ic('share'),'icon-btn','aria-label="放大预览"')}</div></div><div class="artboard-wrap"><div class="artboard ${playing?'music-playing':''}" style="--beat:${60/song().bpm}s" id="artboard" aria-label="作品画布"><div class="scene-bg" style="background-image:url('${e(bgFor(draft.scene))}')"></div><div class="scene-shade"></div><div class="scene-overline"><span>SPACE / ${e(ss.tag)}</span><span class="scene-number">NO. 001</span></div><div class="scene-caption"><span>${e(ss.name)}</span><strong>${e(invite?.caption||draft.caption)}</strong></div>${scenePeople()}<div class="scene-footer"><span>${draft.scene.kind==='photo'?'你的照片，新的故事':'原创虚构场景'}</span><span>STAY A LITTLE LONGER ↗</span></div></div></div><div class="canvas-hint">${ic('user')}拖动分身找个位置 <span>·</span> 方向键微调 <span>·</span> 每一步都可以撤销</div><div class="soundtrack"><button class="play" data-action="play" aria-label="${playing?'暂停':'试听'}原创声景">${ic(playing?'pause':'play')}</button><div class="track-info"><small>这次相遇的 BGM</small><strong>${e(song().title)} <span>· ${e(song().artist)}</span></strong></div><div class="wave ${playing?'playing':''}">${Array.from({length:17},(_,i)=>`<i style="--h:${10+(i*7%21)}px;--d:${i*.08}s"></i>`).join('')}</div>${button('music','换一首','text-btn')}</div></div>
 <aside class="editor-panel"><div class="editor-tabs" role="group" aria-label="编辑工具">${[['scene','场景'],['tune','调一调'],['together','一起出演']].map(([id,label])=>button('tab',label,tab===id?'active':'',`aria-pressed="${tab===id}" data-value="${id}"`)).join('')}</div><div class="editor-body">${tab==='scene'?sceneControls():tab==='tune'?tuneControls():togetherControls()}</div><div class="editor-bottom"><div class="save-status"><i></i>${e(statusLabel())}</div>${primaryAction()}${invite?'':remote?button('save-local-copy',`${ic('bookmark')}收进我的作品`,'secondary save-local'):button('export-solo',`${ic('download')}保存我的图片`,'secondary save-local')}${remote||invite?button('return-draft','返回我的私密草稿','text-btn return-draft'):''}${storageFailed?'<p class="danger">本机存储不足，请导出后再关闭</p>':'<p class="privacy-small">你的分身不会替别人做决定</p>'}</div></aside></section>`}</main><footer class="app-footer"><span>MUSIC SPACE <span class="footer-dot">·</span> MAKE ROOM FOR SOMEONE</span><span>照片和分身合成创作 ${button('about','关于与隐私','text-btn')}</span></footer>`;
 bindCanvas(); mountVisual();
