function visualState(){let host=currentHost(),guest=currentGuest();const appearance=avatarEditing&&avatarDraft?avatarDraft.avatar:draft.avatar;if(!isGuest())host={...host,avatar:appearance,transform:draft.transform};if(isGuest()&&guest)guest={...guest,avatar:appearance,transform:draft.transform};return {scene:{...draft.scene,background:bgFor(draft.scene)},host,guest,playing,bpm:song().bpm,reducedMotion:window.matchMedia?.('(prefers-reduced-motion: reduce)').matches||false};}
function mountVisual(){const stage=$('#artboard');if(stage)stage.classList.toggle('photo-mode',draft.scene.kind==='photo');if(!stage){toon?.update({...visualState(),playing:false});refreshPortraits();return;}if(toonFailed){stage.dataset.renderMode='lite';return;}try{if(!toonLayer){toonLayer=document.createElement('div');toonLayer.className='toon-layer';toonLayer.setAttribute('aria-hidden','true');toonLayer.addEventListener('toonerror',()=>{toonFailed=true;stage.dataset.renderMode='lite';stage.classList.remove('toon-ready');toast('3D 预览暂时不可用，已保留编辑并切换轻量画面',true);});}stage.prepend(toonLayer);if(!toon)toon=mountToonScene(toonLayer,visualState());else toon.update(visualState());stage.classList.add('toon-ready');stage.dataset.renderMode='3d';syncHitAreas();refreshPortraits();}catch(error){console.warn('3D preview unavailable',error.message);toonFailed=true;toon?.dispose();toon=null;toonLayer?.remove();stage.dataset.renderMode='lite';}}
function syncHitAreas(){if(!toon?.getBounds)return;const bounds=toon.getBounds(),mine=isGuest()?'guest':'host';for(const el of document.querySelectorAll('#artboard .person')){const slot=el.dataset.person==='me'?mine:mine==='host'?'guest':'host';if(bounds[slot])el.style.height=bounds[slot].height+'%';}}
function updateVisual(){if(toon&&!toonFailed)try{toon.update(visualState());syncHitAreas();}catch{}}
function portraitFor(a,fullBody=true){if(!toon?.portrait)return null;const key=JSON.stringify([{...a,pose:'listen'},fullBody]);if(portraits.has(key))return portraits.get(key);try{const url=toon.portrait({...a,pose:'listen'},{fullBody,size:320});if(typeof url==='string'){if(portraits.size>=80)portraits.delete(portraits.keys().next().value);portraits.set(key,url);return url;}}catch{}return null;}
function identityPortrait(value){const a=safeAvatar(value);return `<span class="identity-portrait" data-avatar-portrait="${e(JSON.stringify(a))}">${avatarSVG(a)}</span>`;}
function refreshPortraits(){const appearance=avatarEditing&&avatarDraft?avatarDraft.avatar:draft.avatar;
 for(const el of document.querySelectorAll('[data-template],[data-part-key]')){let variant,fullBody=true;if(el.dataset.template!==undefined){variant={...TEMPLATES[Number(el.dataset.template)].avatar,skin:appearance.skin};}else{const key=el.dataset.partKey,value=['accessory','expression','pose'].includes(key)?el.dataset.partValue:Number(el.dataset.partValue);variant={...appearance,[key]:value};fullBody=!['hair','eyewear','expression'].includes(key);}const url=portraitFor(variant,fullBody);if(url)el.innerHTML=`<img src="${url}" alt=""/>`;}
 const url=portraitFor(appearance);if(url){const el=$('.avatar-pedestal');if(el){const child=el.querySelector('svg,img');const img=new Image();img.src=url;img.alt='';img.className='toon-portrait';child?.replaceWith(img);}}
 for(const el of document.querySelectorAll('[data-avatar-portrait]')){try{const a=safeAvatar(JSON.parse(el.dataset.avatarPortrait)),url=portraitFor(a,true);if(url)el.innerHTML=`<img src="${url}" alt=""/>`;}catch{}}
 const mini=$('.profile-mini'),face=portraitFor(profile?.avatar||draft.avatar,false);if(mini&&face)mini.innerHTML=`<img class="toon-portrait" src="${face}" alt=""/>`;
}
function personMarkup(person,own=false){const t=person.transform;return `<div class="person ${own?'editable':''}" ${own?'tabindex="0" role="button" aria-label="移动我的分身：方向键微调位置"':''} style="left:${t.x}%;top:${t.y}%;width:${32*t.scale}%;transform:translate(-50%,-100%) rotate(${t.rotation}deg);z-index:${Math.round(t.y)}" data-person="${own?'me':'other'}">${avatarSVG(person.avatar)}<span class="person-name">${e(person.name)}${own?' · 我':''}</span></div>`;}
function scenePeople(){const host=currentHost(),guest=currentGuest();let result=personMarkup(host,!isGuest()&&!remote);if(remote&&remote.role==='host')result=personMarkup({...host,avatar:draft.avatar,transform:draft.transform},true);if(guest)result+=personMarkup(remote?.role==='guest'?{...guest,avatar:draft.avatar,transform:draft.transform}:guest,isGuest());else result+=`<button class="empty-spot" data-action="invite" style="left:69%;top:72%" aria-label="邀请朋友加入空着的位置"><span class="ghost-avatar">${ic('plus')}</span><strong>这里，留给你</strong></button>`;return result;}
function sceneControls(){return `<div class="panel-heading"><span class="section-no">01 /</span><h2>为这一刻，选个片场。</h2><p>真实 3D 夜景，或你自己的照片。</p></div><div class="scene-options">${scenes.map(s=>`<button class="scene-option ${draft.scene.id===s.id?'selected':''}" data-action="scene" data-value="${s.id}" ${invite||remote?'disabled':''}><img src="${bgFor({kind:'builtin',id:s.id})}" alt="${s.name}原创虚构场景"/><span><strong>${s.name}</strong><small>${s.hint}</small></span><span class="selection-check">${ic('check')}</span></button>`).join('')}</div><div class="or-rule"><span>或者，让生活成为舞台</span></div><label class="upload ${invite||remote?'disabled':''}">${ic('photo')}<span><strong>用自己的照片</strong><small>JPG / PNG / WebP · 最大 15 MB</small></span><input id="photo-input" type="file" accept="image/jpeg,image/png,image/webp" ${invite||remote?'disabled':''}/></label><p class="helper">照片在本机去除元数据。创建邀请前不会上传。</p>${draft.scene.id==='fan-stage'?'<p class="note">「月白」是原创虚构音乐人。同台仅为想象创作，不代表真实艺人参与或代言；邀请真实朋友时会替换此角色。</p>':''}`;}
function tuneControls(){return `<div class="panel-heading"><span class="section-no">02 /</span><h2>像你，也听你的。</h2><p>把每一个细节，调成这一刻的心情。</p></div><label class="field">作品名字<input id="title" maxlength="24" value="${e(draft.title)}" ${invite||remote?'disabled':''}/></label><label class="field">留一句话<textarea id="caption" maxlength="72" rows="2" ${invite||remote?'disabled':''}>${e(draft.caption)}</textarea></label><div class="mobile-poses"><span class="field">出演方式</span><div class="segmented">${POSES.map(([id,label])=>button('pose',label,draft.avatar.pose===id?'active':'',`data-value="${id}" aria-pressed="${draft.avatar.pose===id}"`)).join('')}</div></div><div class="range-row"><label for="scale">分身大小</label><output>${Math.round(draft.transform.scale*100)}%</output></div><input id="scale" type="range" min="0.55" max="1.35" step=".01" value="${draft.transform.scale}"/><div class="range-row"><label for="rotation">身体倾斜</label><output>${draft.transform.rotation}°</output></div><input id="rotation" type="range" min="-20" max="20" step="1" value="${draft.transform.rotation}"/><div class="range-row"><label for="position-y">远近位置</label><output>${Math.round(draft.transform.y)}%</output></div><input id="position-y" type="range" min="45" max="93" value="${draft.transform.y}"/><div class="mini-actions">${button('reset-position',`${ic('refresh')}回到初始位置`,'secondary')}</div><p class="note">人物接触阴影随位置和比例移动。自己的照片不会自动识别遮挡，你可以手动调整构图。</p>`;}
function togetherControls(){
 if(invite)return `<div class="panel-heading"><span class="section-no">03 /</span><h2>我这样加入你。</h2><p>${e(invite.host.name)} 留下的场景，由你带来另一半。</p></div><div class="invitation-note"><span>TA 想对你说</span><p>“${e(invite.caption)}”</p></div><label class="field">你的回应<textarea id="response" maxlength="72" rows="3" placeholder="比如：副歌的这一句，我来唱。">${e(draft.response||'')}</textarea></label><label class="consent-check"><input id="join-consent" type="checkbox" ${draft.joinConsent?'checked':''}/><span>我愿意将自己的分身和回应加入这张作品，让邀请者查看。共同保存另行确认。</span></label><p class="note">加入后仍可调整或退出。只有双方都同意，才能保存共同作品。</p>`;
 if(remote)return `<div class="panel-heading"><span class="section-no">03 /</span><h2>${remote.guest?'两个人，才完整。':'位置留好了。'}</h2><p>${remote.guest?'每一个加入，都值得被认真回应。':'把邀请交给那个你想一起听歌的人。'}</p></div><div class="coauthors">${[remote.host,remote.guest].filter(Boolean).map(p=>`<div>${identityPortrait(p.avatar)}<strong>${e(p.name)}</strong><small>${p.id===session?.user?.id?'我':'共同出演'}</small></div>`).join('')}${remote.guest?'':'<div class="await-avatar">＋<small>等一个朋友</small></div>'}</div>${remote.role==='guest'?`<label class="field">你的回应<textarea id="response" maxlength="72" rows="2">${e(draft.response||'')}</textarea></label>`:''}${remote.guest?`<div class="invitation-note"><span>${e(remote.guest.name)} 的回应</span><p>“${e(remote.guest.response||'一起听这首歌。')}”</p></div>`:''}${remote.status==='pending'&&remote.role==='host'?`<div class="decision-actions">${button('accept',`${ic('check')}喜欢这个版本`,'primary')}${button('reject','请朋友再调整一下','text-btn')}</div>`:''}${remote.status==='accepted'?`<label class="consent-check"><input id="share-consent" type="checkbox" ${remote.consents[remote.role]?'checked':''}/><span>我同意双方保存当前版本的合成图片。保存后的副本无法远程撤回。</span></label><div class="consent-status"><span>${remote.consents.host?'✓':'○'} ${e(remote.host.name)} 同意保存</span><span>${remote.consents.guest?'✓':'○'} ${e(remote.guest?.name)} 同意保存</span></div>`:''}${remote.role==='host'?button('copy-invite',`${ic('link')}${remote.inviteActive&&inviteLink?'复制邀请链接':'重新生成邀请'}`,'secondary',remote.guest?'disabled':''):button('leave','退出这张共同作品','text-btn danger')}${remote.role==='host'&&remote.inviteActive?button('revoke','关闭邀请入口','text-btn danger'):''}<p class="note">邀请链接只用于这张作品，不会公开你的其它草稿。转发链接的人也可以看到邀请内容。</p>`;
 return `<div class="panel-heading"><span class="section-no">03 /</span><h2>给你，留个位置。</h2><p>不是点赞，而是带着自己的样子加入。</p></div><div class="together-illustration">${identityPortrait(draft.avatar)}<span class="dashed-seat">＋</span><i>see you here ↗</i></div><ol class="steps"><li><b>01</b><span><strong>先留下你的那一半</strong><small>场景、分身，还有想分享的歌。</small></span></li><li><b>02</b><span><strong>朋友决定怎样加入</strong><small>自己的形象、动作和一句回应。</small></span></li><li><b>03</b><span><strong>两个人点头，收好这一刻</strong><small>共同确认之后，保存双人作品。</small></span></li></ol>`;}
function primaryAction(){if(invite)return button('join',`带着我的分身加入 ${ic('arrow')}`,'primary',busy?'disabled':'');if(remote&&isDirty())return button('update-remote','保存我的调整','primary',busy?'disabled':'');if(remote?.exportEligible)return button('export-joint',`${ic('download')}保存我们的作品`,'primary',busy?'disabled':'');if(remote&&remote.role==='guest')return button('update-remote','保存我的调整','primary',busy?'disabled':'');if(remote)return button('refresh',`${ic('refresh')}查看朋友的回应`,'primary',busy?'disabled':'');return button('invite',`给朋友留个位置 ${ic('arrow')}`,'primary',busy?'disabled':'');}
function worksPage(){return `<section class="studio-heading"><div><div class="eyebrow">LITTLE MOMENTS, KEPT FOREVER</div><h1>我们留下的，不止照片。</h1><p>私密草稿与共同作品，都在这里慢慢积攒。</p></div>${button('new',`${ic('plus')}新的相遇`,'primary')}</section><div class="works-grid">${works.map(w=>`<article class="work-card"><button data-action="open-work" data-value="${e(w.id)}"><div class="work-image" style="background-image:url('${e(w.preview||bgFor(w.scene))}')">${w.preview?'':`<div class="work-avatar">${identityPortrait(w.avatar||DEFAULT_AVATAR)}</div>`}<span class="work-tag">${w.remoteId?'双人共创':'本机私藏'}</span></div><div class="work-details"><small>${new Date(w.savedAt).toLocaleDateString('zh-CN')} / ${e(SONGS.find(s=>s.id===w.songId)?.title||'原创声景')}</small><h2>${e(w.title)}</h2><p>${e(w.caption)}</p></div></button><button data-action="delete-work" data-value="${e(w.id)}" class="icon-btn delete-work" aria-label="删除本机作品 ${e(w.title)}">${ic('trash')}</button></article>`).join('')}<button class="new-work" data-action="new"><span>＋</span><strong>下次见面，听什么？</strong><small>从新的场景开始</small></button></div>`;}
function bindCanvas(){const el=$('[data-person="me"]');if(!el)return;let drag=null;el.addEventListener('pointerdown',event=>{if(event.button!==0)return;const r=$('#artboard').getBoundingClientRect();drag={start:clone(draft),x:event.clientX,y:event.clientY,r,moved:false};el.setPointerCapture(event.pointerId);el.classList.add('dragging');event.preventDefault();});el.addEventListener('pointermove',event=>{if(!drag)return;const dx=(event.clientX-drag.x)/drag.r.width*100,dy=(event.clientY-drag.y)/drag.r.height*100;if(Math.abs(dx)+Math.abs(dy)>.3)drag.moved=true;draft.transform.x=Math.round(clamp(drag.start.transform.x+dx,14,86)*10)/10;draft.transform.y=Math.round(clamp(drag.start.transform.y+dy,45,94)*10)/10;el.style.left=draft.transform.x+'%';el.style.top=draft.transform.y+'%';el.style.zIndex=Math.round(draft.transform.y);updateVisual();});const end=()=>{if(!drag)return;if(drag.moved){history.push(drag.start);redo=[];persist();}drag=null;el.classList.remove('dragging');};el.addEventListener('pointerup',()=>{end();render();});el.addEventListener('pointercancel',()=>{if(drag)draft=drag.start;drag=null;render();});el.addEventListener('keydown',event=>{const dirs={ArrowLeft:[-1,0],ArrowRight:[1,0],ArrowUp:[0,-1],ArrowDown:[0,1]};if(!dirs[event.key])return;event.preventDefault();const m=event.shiftKey?5:1;commit(d=>{d.transform.x=clamp(d.transform.x+dirs[event.key][0]*m,14,86);d.transform.y=clamp(d.transform.y+dirs[event.key][1]*m,45,94);});$('[data-person="me"]')?.focus();});}
function openModal(html,cls=''){
 const updating=modal.open&&cls.includes('avatar-drawer')&&modal.className.includes('avatar-drawer');
 const focused=updating?document.activeElement:null;const focusData=focused?.dataset?{action:focused.dataset.action,key:focused.dataset.key,value:focused.dataset.value}:null;
 if(!modal.open)lastFocus=document.activeElement;modal.className=cls;modal.innerHTML=`<button class="modal-close icon-btn" data-action="close-modal" aria-label="${cls.includes('avatar-drawer')?'取消分身修改':'关闭'}">${ic('close')}</button>${html}`;
 const heading=modal.querySelector('h2');if(heading){heading.id='modal-title';modal.setAttribute('aria-labelledby','modal-title');}else{modal.removeAttribute('aria-labelledby');modal.setAttribute('aria-label','画面预览');}
 if(!modal.open)modal.showModal();refreshPortraits();
 setTimeout(()=>{let target;if(updating&&focusData?.action){target=[...modal.querySelectorAll('[data-action]')].find(el=>el.dataset.action===focusData.action&&el.dataset.key===focusData.key&&el.dataset.value===focusData.value);}if(!target)target=cls.includes('avatar-drawer')?modal.querySelector('[data-action="avatar-category"].active'):modal.querySelector('input,button:not(.modal-close),textarea');target?.focus({preventScroll:true});},10);
}
function closeModal(){const wasEditing=avatarEditing;avatarEditing=false;document.body.classList.remove('wardrobe-open');modal.close();modal.innerHTML='';if(wasEditing){render();updateVisual();}if(lastFocus?.isConnected)lastFocus.focus();else if(wasEditing)$('[data-action=avatar]')?.focus();}
modal.addEventListener('click',ev=>{if(ev.target===modal){const r=modal.getBoundingClientRect();if(ev.clientX<r.left||ev.clientX>r.right||ev.clientY<r.top||ev.clientY>r.bottom)closeModal();}});
modal.addEventListener('cancel',ev=>{ev.preventDefault();closeModal();});
let avatarDraft=null;
function avatarDialog(){avatarDraft={name:profile?.name||'',avatar:safeAvatar(draft.avatar)};avatarEditing=true;avatarCategory='presets';document.body.classList.add('wardrobe-open');renderAvatarDialog(true);}
const wardrobeTabs=[['presets','搭配'],['hair','发型'],['eyewear','眼镜'],['top','上装'],['bottom','下装'],['shoes','鞋履'],['accessory','配件'],['expression','表情'],['pose','动作'],['colors','配色']];
function wardrobeOptions(){const a=avatarDraft.avatar,key=avatarCategory;
 if(key==='presets')return `<div class="wardrobe-section-title"><h3>从一套搭配开始。</h3><p>名字和肤色不变，每一件都能单独换。</p></div><div class="component-grid presets-grid">${TEMPLATES.map((t,i)=>`<button class="component-card ${['hair','top','bottom','shoes','eyewear'].every(k=>a[k]===t.avatar[k])?'selected':''}" data-action="avatar-template" data-value="${i}"><span class="component-portrait" data-template="${i}">${avatarSVG({...t.avatar,skin:a.skin})}</span><strong>${t.name}<small>${t.english}</small></strong><span class="component-detail">${t.note}</span></button>`).join('')}</div>`;
 if(key==='colors')return `<div class="wardrobe-section-title"><h3>你的配色，没有标准答案。</h3><p>一件一件调，不会改掉其它部件。</p></div>${swatches('skin','肤色',SKINS,a.skin)}${swatches('hairColor','发色',HAIRS,a.hairColor)}${swatches('topColor','上装颜色',GARMENT_COLORS,a.topColor)}${swatches('bottomColor','下装颜色',GARMENT_COLORS,a.bottomColor)}${swatches('shoeColor','鞋履颜色',GARMENT_COLORS,a.shoeColor)}`;
 const entries=key==='pose'?POSES.map(([id,label])=>[id,label,'']):(COMPONENTS[key]||[]).map((entry,i)=>['accessory','expression'].includes(key)?entry:[i,...entry]);
 const title=wardrobeTabs.find(t=>t[0]===key)?.[1]||'';
 return `<div class="wardrobe-section-title"><h3>只换${title}，其它由你保留。</h3><p>${entries.length} 种选择 · 可与所有已选部件自由组合</p></div><div class="component-grid ${['hair','eyewear','expression'].includes(key)?'head-parts':''}">${entries.map(([value,label,english])=>{const variant={...a,[key]:value};return `<button class="component-card ${a[key]===value?'selected':''}" data-action="avatar-option" data-key="${key}" data-value="${value}" aria-pressed="${a[key]===value}"><span class="component-portrait" data-part-key="${key}" data-part-value="${value}">${avatarSVG(variant)}</span><strong>${label}<small>${english}</small></strong></button>`;}).join('')}</div>`;
}
function renderAvatarDialog(resetScroll=false){const scroll=resetScroll?0:$('.wardrobe-content')?.scrollTop||0;
 openModal(`<div class="wardrobe-head"><span class="modal-kicker">SPACE / LOOK LAB</span><h2>你的形象，你说了算。</h2><p>搭配是起点。每一件，都可以自由组合。</p></div><label class="wardrobe-name"><span>署名</span><input id="avatar-name" maxlength="18" placeholder="你的名字" value="${e(avatarDraft.name)}" autocomplete="nickname"/></label><div class="wardrobe-tabs" role="group" aria-label="选择造型部件">${wardrobeTabs.map(([id,label])=>button('avatar-category',label,avatarCategory===id?'active':'',`data-value="${id}" aria-pressed="${avatarCategory===id}"`)).join('')}</div><div class="wardrobe-content">${wardrobeOptions()}</div><div class="wardrobe-footer"><span>当前为预览 · 保存后才更新你的分身</span><div>${button('close-modal','取消','secondary')}${button('save-avatar',`保存分身 ${ic('check')}`,'primary')}</div></div>`,'avatar-modal avatar-drawer');
 const content=$('.wardrobe-content');if(content)content.scrollTop=scroll;refreshPortraits();updateVisual();
 if(toonFailed){const el=$('[data-person="me"]');const svg=el?.querySelector('svg');if(svg)svg.outerHTML=avatarSVG(avatarDraft.avatar);}
}
function swatches(key,label,colors,selected){return `<div class="field"><span>${label}</span><div class="swatches">${colors.map((c,i)=>button('avatar-option',selected===i?ic('check'):'',selected===i?'selected':'',`style="--swatch:${c}" data-key="${key}" data-value="${i}" aria-label="${label} ${i+1}" aria-pressed="${selected===i}"`)).join('')}</div></div>`;}
function musicDialog(){openModal(`<div class="modal-kicker">A SONG TO SHARE</div><h2>把心情放进这首歌。</h2><p class="modal-intro">三段原创合成声景，点击试听 24 秒。没有商业歌曲录音。</p><div class="music-options">${SONGS.map(s=>`<button data-action="choose-song" data-value="${s.id}" class="music-option ${draft.songId===s.id?'selected':''}" ${invite||remote?'disabled':''}><span class="record" style="--record:${s.color}"><i></i></span><span><small>${s.tag}</small><strong>${s.title}</strong><p>${s.mood}</p></span><span>${draft.songId===s.id?ic('check'):ic('arrow')}</span></button>`).join('')}</div><p class="note">音乐影响这次相遇的气氛与动作建议，分身的长相仍由你决定。</p>`);}
function aboutDialog(){openModal(`<div class="modal-kicker">A SMALL, HONEST SPACE</div><h2>亲近，也有边界。</h2><div class="about-copy"><p>Space 是一个以分身为身份的双人创作工作室。场景与原创虚构音乐人由创作生成，不是真实艺人参与、真实合照或代言。</p><h3>从私密草稿，到两个人的作品</h3><p>普通草稿、上传照片和分身先保存在当前浏览器。照片在本机重绘，移除原始元数据。只有你主动创建邀请，当前作品才会传到共创服务。</p><p>任何持有邀请链接的人都能看见邀请中的照片、你的分身、昵称和留言。链接不暴露你的其它作品，可随时关闭入口。</p><p>朋友用自己的身份加入。你确认这个版本后，双方还要分别同意保存，才能导出共同作品。任何一方修改都会重新确认；已经下载的副本不能远程撤回。</p><h3>设备和连接</h3><p>匿名身份凭证只保存在本机，尚无账号找回。清除浏览器数据会失去访问权。本机作品不自动同步；请及时导出。已载入的页面离线仍可继续创作，双人邀请与共同保存需要连接共创服务。</p><p>画布使用手工可控的位置、姿态与阴影，不声称自动识别照片遮挡。音乐试听是本项目程序生成的原创声景。</p></div>${button('close-modal','知道了','primary')}`);}
async function withBusy(fn){if(busy)return;const generation=routeGeneration,workId=remote?.id,joiningToken=invite?inviteToken:null;busy=true;document.body.classList.add('busy');try{await fn();}catch(err){if(generation!==routeGeneration)return;if(err.status===409&&err.code==='REVISION_CONFLICT'){if(joiningToken&&inviteToken===joiningToken&&invite){toast('邀请内容刚刚更新。你的造型和回应仍在，请查看新画面后重新勾选同意。',true);draft.joinConsent=false;persist();await refreshInvitation(joiningToken,generation).catch(()=>{});}else if(remote?.id===workId){toast('对方刚刚修改了作品。你的调整仍在，请查看新版本后再保存。',true);await refreshRemote(true).catch(()=>{});}}else if(err.status===401){toast('本机身份已失效。草稿已保留；请重新建立身份，旧共同作品不会自动找回。',true);openModal(`<h2>身份需要重新建立</h2><p class="modal-intro">草稿和分身还在这台设备。旧身份对应的共同作品无法自动找回。</p>${button('reset-session','保留草稿，建立新身份','primary')}`);}else toast(err.message||'没有完成，请重试',true);}finally{busy=false;document.body.classList.remove('busy');render();}}
async function ensureSession(){if(!profile){avatarDialog();throw Error('先创建一个属于你的分身，再邀请朋友');}if(session){await request('/session',{token:session.token});return session;}const r=await request('/session',{method:'POST',body:profile});session=r;try{localStorage.setItem(SESSION_KEY,JSON.stringify(session));}catch{session=null;throw Error('浏览器无法保存新的身份，请先释放本机存储空间再邀请。草稿仍在。');}persist();return r;}
async function syncProfile(){if(!session)return;const fresh=await request('/session',{token:session.token});session.user=fresh.user;const r=await request('/profile',{method:'PUT',token:session.token,body:{...profile,revision:session.user.revision}});session.user=r.user;localStorage.setItem(SESSION_KEY,JSON.stringify(session));persist();}
function remoteDraft(c,preserve=false){remote=c;inviteLink=c.inviteActive?(inviteLinks[c.id]||''):'';const me=c[c.role];if(!preserve)draft={...newDraft(me.avatar),id:c.id,title:c.title,caption:c.caption,scene:c.scene,songId:c.songId,avatar:safeAvatar(me.avatar),transform:clone(me.transform),response:me.response||''};persist();}
async function loadPhoto(scene,token,revision=''){const generation=routeGeneration;const cacheKey=scene.photoUrl+'@'+revision;if(scene.kind!=='photo'||scene.dataUrl)return;if(cacheKey===photoKey)return;const url=await photoBlob(scene.photoUrl,token);if(generation!==routeGeneration){URL.revokeObjectURL(url);return;}if(photoURL)URL.revokeObjectURL(photoURL);photoURL=url;photoKey=cacheKey;}
async function refreshInvitation(token=inviteToken,generation=routeGeneration){const r=await request(`/invites/${encodeURIComponent(token)}`);if(generation!==routeGeneration||!invite||inviteToken!==token)return;invite=r.preview;draft={...draft,title:invite.title,caption:invite.caption,scene:invite.scene,songId:invite.songId,joinConsent:false};persist();await loadPhoto(invite.scene,null,invite.revision);if(generation===routeGeneration&&inviteToken===token)render();}
function onWorkRoute(generation,id){return generation===routeGeneration&&remote?.id===id;}
async function refreshRemote(preserve=false){if(!remote||!session)return;const id=remote.id,generation=routeGeneration;const {composition:c}=await request(`/compositions/${id}`,{token:session.token});if(generation!==routeGeneration||remote?.id!==id)return;remoteDraft(c,preserve);await loadPhoto(c.scene,session.token,c.contentRevision);rememberRemote(c);render();}
function rememberRemote(c){const w={id:c.id,remoteId:c.id,title:c.title,caption:c.caption,scene:c.scene.kind==='builtin'?c.scene:{kind:'photo'},songId:c.songId,avatar:c.host.avatar,savedAt:c.updatedAt};const i=works.findIndex(x=>x.id===c.id);if(i<0)works.unshift(w);else works[i]={...works[i],...w};persist();}
async function createInvitation(){if(!profile){avatarDialog();return;}if(connected===false){openModal(`<div class="modal-kicker">YOUR DRAFT IS SAFE</div><h2>先把这一刻留在本机。</h2><p class="modal-intro">当前是静态创作模式。跨设备邀请需要共创服务；本机创作、分身调整与单人导出都能继续。</p><div class="modal-actions">${button('close-modal','继续创作','secondary')}${button('export-solo','保存我的图片','primary')}</div>`);return;}if(remote){tab='together';render();return;}openModal(`<div class="modal-kicker">SAVE A PLACE FOR SOMEONE</div><h2>这里，留给谁都不一样。</h2><p class="modal-intro">创建邀请会上传当前场景或照片、你的分身、昵称与留言。任何拿到链接的人都能预览这张邀请。</p><div class="invite-summary"><span class="mini-avatar">${identityPortrait(draft.avatar)}</span><div><strong>${e(draft.title)}</strong><p>${e(draft.caption)}</p><small>♫ ${e(song().title)}</small></div></div><p class="note">朋友用自己的分身加入。加入不代表允许导出；共同保存仍需双方分别同意。</p><div class="modal-actions">${button('close-modal','再调一调','secondary')}${button('confirm-invite',`创建私密邀请 ${ic('arrow')}`,'primary')}</div>`);}
async function confirmInvitation(){
 const generation=routeGeneration,reviewed=clone(draft),existing=remote?clone(remote):null;
 await ensureSession();if(generation!==routeGeneration)return;let c=existing;
 if(!c){const result=await request('/compositions',{method:'POST',token:session.token,body:{title:reviewed.title,caption:reviewed.caption,scene:reviewed.scene,songId:reviewed.songId,avatar:reviewed.avatar,transform:reviewed.transform}});c=result.composition;rememberRemote(c);if(generation===routeGeneration){localDraft=reviewed;remoteDraft(c);history=[];redo=[];historyReplace(`#work=${c.id}`);await loadPhoto(c.scene,session.token,c.contentRevision);}}
 const r=await request(`/compositions/${c.id}/invite`,{method:'POST',token:session.token,body:{revision:c.revision}});inviteLinks[c.id]=`${location.href.split('#')[0]}#invite=${encodeURIComponent(r.inviteToken)}`;rememberRemote(r.composition);
 if(generation!==routeGeneration){toast('邀请已创建，可以从我的作品继续');return;}
 remoteDraft(r.composition);inviteToken=r.inviteToken;inviteLink=`${location.href.split('#')[0]}#invite=${encodeURIComponent(inviteToken)}`;inviteLinks[c.id]=inviteLink;persist();tab='together';render();inviteDialog();
}
