async function updateRemote(){if(!isDirty()){toast('当前版本已经保存');return;}const generation=routeGeneration,id=remote.id,body=clone({revision:remote.revision,avatar:draft.avatar,transform:draft.transform,...(remote.role==='guest'?{response:draft.response??remote.guest?.response??''}:{})});const {composition:c}=await request(`/compositions/${id}`,{method:'PATCH',token:session.token,body});if(!onWorkRoute(generation,id))return;remoteDraft(c);rememberRemote(c);render();toast('调整已保存。双方需重新确认这个版本。');}
