async function openRoute(){
 const generation=++routeGeneration,hash=location.hash.slice(1);routeLoading=hash.startsWith('invite=')||hash.startsWith('work=');if(routeLoading&&!remote&&!invite)localDraft=clone(draft);if(modal.open&&(routeLoading||remote||invite))closeModal();render();
 try{
  if(hash.startsWith('invite=')){
   inviteToken=decodeURIComponent(hash.slice(7));
   const r=await request(`/invites/${encodeURIComponent(inviteToken)}`);if(generation!==routeGeneration)return;
   if(r.preview.host.id===session?.user?.id){historyReplace(`#work=${r.preview.id}`);await openRoute();return;}
   history=[];redo=[];invite=r.preview;remote=null;
   draft={...newDraft(profile?.avatar),title:invite.title,caption:invite.caption,scene:invite.scene,songId:invite.songId,transform:{x:66,y:81,scale:1,rotation:0}};
   await loadPhoto(invite.scene,null,invite.revision);if(generation!==routeGeneration)return;tab='together';view='studio';
  }else if(hash.startsWith('work=')){
   if(!session)throw Error('这张共同作品需要原来的浏览器身份。昵称无法恢复旧身份。');
   const {composition:c}=await request(`/compositions/${encodeURIComponent(hash.slice(5))}`,{token:session.token});if(generation!==routeGeneration)return;
   const pending=pendingEdits[c.id];invite=null;remoteDraft(c);
   if(pending?.avatar&&pending?.transform){draft.avatar=pending.avatar;draft.transform=pending.transform;draft.response=pending.response||'';persist();toast('已恢复这张作品上未保存的调整');}
   history=[];redo=[];await loadPhoto(c.scene,session.token,c.contentRevision);if(generation!==routeGeneration)return;view='studio';tab='together';
  }else if(remote||invite){persist();remote=null;invite=null;inviteToken=null;inviteLink='';draft=clone(localDraft);history=[];redo=[];view='studio';tab='scene';persist();}
 }catch(err){if(generation!==routeGeneration)return;openModal(`<div class="modal-kicker">YOUR PRIVATE DRAFT IS SAFE</div><h2>这一刻，暂时没能打开。</h2><p class="modal-intro">${e(err.message)}</p><p class="note">你的个人分身和本机草稿还在。邀请关闭或过期时，可以请对方重新邀请。</p><div class="modal-actions">${button('cancel-route','回私密草稿','secondary')}${button('retry-route','重新连接','primary')}</div>`);
 }finally{if(generation===routeGeneration){routeLoading=false;render();}}
}
